package gymmie;

import java.io.IOException;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.control.Label;

/**
 * Controls the main Gymmie view.
 */
public class MainController {

    @FXML
    private Label welcomeLabel;

    /**
     * Initializes the starter view.
     */
    @FXML
    private void initialize() {
        welcomeLabel.setText("Your fitness journey starts here.");
    }

    /**
     * Opens the settings view in the current application window.
     */
    @FXML
    private void openSettings() {
        try {
            FXMLLoader loader = new FXMLLoader(
                    MainController.class.getResource("/gymmie/view/Settings.fxml"));
            Parent settingsView = loader.load();
            welcomeLabel.getScene().setRoot(settingsView);
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to open the settings view", exception);
        }
    }
}
package gymmie;

import java.io.IOException;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;

/**
 * Controls the Gymmie settings view.
 */
public class SettingsController {

    @FXML
    private TextField nameField;

    @FXML
    private Label saveStatusLabel;

    /**
     * Returns to the home view in the current application window.
     */
    @FXML
    private void goBack() {
        try {
            FXMLLoader loader = new FXMLLoader(
                    SettingsController.class.getResource("/gymmie/view/MainWindow.fxml"));
            Parent homeView = loader.load();
            nameField.getScene().setRoot(homeView);
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to return to the home view", exception);
        }
    }

    /**
     * Shows confirmation feedback after the user saves their preferences.
     */
    @FXML
    private void saveSettings() {
        saveStatusLabel.setText("Settings saved");
    }
}
